const eventos = [];
const ahora = new Date();
const hoyStr = ahora.toLocaleDateString('en-CA', { timeZone: 'America/Mexico_City' });

// Validación local de sintaxis; no verifica propiedad ni disponibilidad del enlace.
function enlaceValido(value) {
  if (typeof value !== 'string' || !/^https:[/][/]/i.test(value) || /[\s\\]/.test(value)) return false;
  try {
    const url = new URL(value);
    const labels = url.hostname.split('.');
    return url.protocol === 'https:' && !url.username && !url.password &&
      !value.slice(8).split(/[/?#]/)[0].includes('@') && labels.length > 1 &&
      labels.every(label => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(label));
  } catch { return false; }
}

for (const item of $input.all()) {
  const evento = item?.json;
  if (!evento || typeof evento !== 'object' || Array.isArray(evento) || evento.status === 'cancelled') continue;
  if (evento.summary != null && typeof evento.summary !== 'string') continue;

  // ISO con zona explícita, sin all-day ni normalización de fechas imposibles.
  const startStr = evento.start?.dateTime;
  if (typeof startStr !== 'string') continue;
  const iso = startStr.match(/^(\d{4})-(\d{2})-(\d{2})T([01]\d|2[0-3]):([0-5]\d):([0-5]\d)(?:\.\d{1,3})?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)$/);
  if (!iso) continue;
  const year = Number(iso[1]), month = Number(iso[2]), day = Number(iso[3]);
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (month < 1 || month > 12 || day < 1 || day > days[month - 1]) continue;
  const startDate = new Date(startStr);
  if (!Number.isFinite(startDate.getTime()) || startDate < ahora) continue;
  const fechaEvento = startDate.toLocaleDateString('en-CA', { timeZone: 'America/Mexico_City' });

  // Solo eventos de HOY
  if (fechaEvento !== hoyStr) continue;

  const hora = startDate.toLocaleString('es-MX', {
    timeZone: 'America/Mexico_City',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true
  });

  // Usar el enlace principal o un punto de entrada HTTPS de video.
  const entryPoints = evento.conferenceData?.entryPoints;
  const hangoutLink = evento.hangoutLink || (Array.isArray(entryPoints) ?
    entryPoints.find(entry => entry && (!entry.entryPointType || entry.entryPointType === 'video') && enlaceValido(entry.uri))?.uri : '') || '';
  if (!enlaceValido(hangoutLink)) continue;

  // Un único marcador, en su propia línea: duplicados/conflictos fallan cerrado.
  const description = evento.description;
  if (typeof description !== 'string' || (description.match(/CONVERSATION_ID:/g) || []).length !== 1) continue;
  const convMatch = description.match(/^CONVERSATION_ID:[ \t]*([1-9]\d*)[ \t]*\r?$/m);
  if (!convMatch || !Number.isSafeInteger(Number(convMatch[1]))) continue;
  const conversationId = convMatch[1];

  // Extraer WhatsApp del summary (despues del ultimo " - ")
  const summary = evento.summary || '';
  const parts = summary.split(' - ');
  const whatsapp = parts.length > 1 ? parts[parts.length - 1].trim().replace(/^\+/, '') : '';

  eventos.push({
    json: {
      hora: hora,
      hangoutLink: hangoutLink,
      conversation_id: conversationId,
      whatsapp: whatsapp,
      summary: summary
    }
  });
}

return eventos;
